content.text:
{
  "name": "TC038D烘箱温控器",
  "name_en": "TC038D Oven Temperature Controller",
  "manufacturer": "HCP",
  "description": "用于控制HCP TC038D烘箱的温度控制器，可通过Modbus原始字节通信读取寄存器、写入参数、设置温度设定值并监测当前温度，适用于实验中的加热与恒温控制。",
  "description_en": "A temperature controller for the HCP TC038D oven. It communicates via Modbus raw bytes to read registers, write parameters, set the temperature setpoint, and monitor the current temperature for laboratory heating and temperature regulation.",
  "actions": [
    {
      "action_name": "auto-readRegister",
      "description": "读取指定地址开始的寄存器数据。",
      "description_en": "Read register data starting from the specified address."
    },
    {
      "action_name": "auto-setpoint",
      "description": "获取/设置温度设定值。",
      "description_en": "Get/set the temperature setpoint."
    },
    {
      "action_name": "auto-writeMultiple",
      "description": "向指定地址写入多个寄存器值。",
      "description_en": "Write multiple register values to the specified address."
    },
    {
      "action_name": "auto-CRC16",
      "description": "计算数据字节数组的CRC16校验值。",
      "description_en": "Calculate the CRC16 checksum for a byte array."
    },
    {
      "action_name": "auto-temperature",
      "description": "获取当前温度。",
      "description_en": "Get the current temperature."
    }
  ],
  "tag_hints": [
    "oven temperature control",
    "Modbus RTU communication",
    "temperature setpoint",
    "process temperature monitoring",
    "DC heating",
    "laboratory oven"
  ]
}

